// ADMINISTRATOR — VENUE OPERATIONS (Round 37-V, Eddie 2026-11-20).
// Eddie's window on the venue business. Two doors, both on his
// Profile: the Owner Mode section's door (R37-V) and, since
// Round 37-V2, the Administrator portal at the bottom of Profile
// — a password door Eddie sets himself, after the first door
// proved too easy to miss. The route shows nothing to a direct
// arrival with neither Owner Mode nor a portal unlock this
// session. The doors guard the entrance only: the DATA in here
// still opens solely to a signed-in owner email (Supabase RLS).
// Kept in the background until launch — no public surface links
// here.
//
// Structure is Eddie's geographic drill-down, exactly:
//   REGIONS → STATES → CITIES A–Z (grouped under in-state areas
//   where the data has them — SoCal is the live example) → at
//   every level, the operations running there: applications
//   waiting on Eddie, approved/live venues with their saved
//   profiles, refill stations.
//
// PRIVACY LAW, no exceptions (Eddie's clarification, 2026-11-20
// 18:45): this window holds venue/business records and AGGREGATE
// crowd counts (Pulse, Round 37-V3) — heat, check-in totals, the
// hottest areas, per-venue visit counts. The ban is on INDIVIDUAL
// data: no names, no individual locations, no live tracking, no
// per-person anything, ever — not even for Eddie. Aggregate counts
// obey the suppression floor in utils/pulse.ts: a place under 10
// shows words, not a number, so nobody can be singled out.
//
// Data: public.venue_applications (Supabase), read/written only
// through RLS — SELECT/UPDATE open solely to signed-in owner
// emails. Until the migration SQL has been run the table does not
// exist and this window says so honestly instead of inventing data.

const STATUS_LABEL: Record<VenueStatus, string> = {
  applied: 'Waiting on you',
  approved: 'Approved — profile saved',
  declined: 'Declined',
  live: 'Live',
};

interface Counts {
  waiting: number;
  approved: number;
  live: number;
  declined: number;
}

function countRows(rows: VenueApplicationRow[]): Counts {
  return {
    waiting: rows.filter(r => r.status === 'applied').length,
    approved: rows.filter(r => r.status === 'approved').length,
    live: rows.filter(r => r.status === 'live').length,
    declined: rows.filter(r => r.status === 'declined').length,
  };
}

function CountChips({ counts, stations }: { counts: Counts; stations?: number }) {
  return (
    <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
      {counts.waiting > 0 && (
        <Chip size="small" color="warning" label={`${counts.waiting} waiting`} />
      )}
      {counts.approved > 0 && (
        <Chip size="small" color="info" label={`${counts.approved} approved`} />
      )}
      {counts.live > 0 && <Chip size="small" color="success" label={`${counts.live} live`} />}
      {counts.declined > 0 && <Chip size="small" label={`${counts.declined} declined`} />}
      {counts.waiting + counts.approved + counts.live + counts.declined === 0 && !stations && (
        <Chip size="small" variant="outlined" label="No venues yet" />
      )}
      {!!stations && <Chip size="small" variant="outlined" label={`${stations} refill stations`} />}
    </Box>
  );
}

// The floor-safe GLACER-visits line every venue and station card
// carries (Round 37-V3): this is the number a venue gets told —
// and under the floor it is words, never a small numeral.
const VisitsLine: React.FC<{ targetId: string }> = ({ targetId }) => {
  const counts = useMemo(() => pulseCountsFor(targetId), [targetId]);
  return (
    <Typography
      variant="caption"
      color="text.secondary"
      display="block"
      data-testid={`venue-visits-${targetId}`}
    >
      GLACER visits — this week: {floorText(counts.week)} · all time: {floorText(counts.total)}
    </Typography>
  );
};

const FEEL_COLOR: Record<string, string> = {
  Buzzing: '#ef5350',
  Active: '#ffa726',
  'Warming up': '#ffee58',
  Quiet: '#90a4ae',
};

// PULSE (Round 37-V3) — the crowd in aggregate: new users, total
// check-ins, the hottest area, heat by area, per-venue visits (on
// the cards below) and the soft notification feed ("people were
// there" — never who). Every number comes from utils/pulse.ts;
// activity is the on-device demo layer and says so, the new-user
// count is a real count-only query when it can be read and says
// which it is on its own card.
const PulseSection: React.FC = () => {
  const snapshot = useMemo(
    () => ({ totals: totalCheckinCounts(), heat: heatByArea(), hottest: hottestArea() }),
    []
  );
  const [newUsers, setNewUsers] = useState<NewUserCounts | null>(null);
  const [notices, setNotices] = useState<PulseNotice[]>([]);

  useEffect(() => {
    setNotices(syncPulseNotices());
    let live = true;
    void fetchNewUserCounts().then(c => {
      if (live) setNewUsers(c);
    });
    return () => {
      live = false;
    };
  }, []);

  const hot = snapshot.hottest;

  return (
    <Paper sx={{ p: 3, mb: 3 }} data-testid="pulse-section">
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          📊 Pulse — the shape of the crowd
        </Typography>
        <Chip size="small" variant="outlined" label="Demo activity" />
      </Box>
      <Typography variant="body2" color="text.secondary" paragraph>
        Demo activity — live numbers arrive as real players check in. Pulse holds counts only: no
        names, no pins, no person's trail. A place under {PULSE_FLOOR} check-ins shows words, not a
        number, so nobody can be singled out — and players who go Invisible are never counted at
        all.
      </Typography>

      <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 2 }}>
        <Paper variant="outlined" sx={{ p: 2, flex: '1 1 180px' }} data-testid="pulse-new-users">
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="subtitle2" sx={{ flexGrow: 1 }}>
              New users
            </Typography>
            {newUsers && (
              <Chip
                size="small"
                color={newUsers.source === 'live' ? 'success' : 'default'}
                label={newUsers.source === 'live' ? 'Live count' : 'Demo'}
                data-testid="pulse-new-users-source"
              />
            )}
          </Box>
          {newUsers ? (
            <Typography variant="body2" color="text.secondary">
              Today {newUsers.today} · This week {newUsers.week} · Total {newUsers.total}
            </Typography>
          ) : (
            <Typography variant="body2" color="text.secondary">
              Counting…
            </Typography>
          )}
        </Paper>

        <Paper variant="outlined" sx={{ p: 2, flex: '1 1 180px' }} data-testid="pulse-checkins">
          <Typography variant="subtitle2">Check-ins</Typography>
          <Typography variant="body2" color="text.secondary">
            Today {snapshot.totals.today} · This week {snapshot.totals.week} · All time{' '}
            {snapshot.totals.total}
          </Typography>
        </Paper>

        <Paper variant="outlined" sx={{ p: 2, flex: '1 1 180px' }} data-testid="pulse-hottest">
          <Typography variant="subtitle2">Hottest area</Typography>
          {hot ? (
            <Typography variant="body2" color="text.secondary">
              {hot.city}
              {hot.area ? ` · ${hot.area}` : ''} — {hot.feel}
              {hot.counts.week >= PULSE_FLOOR
                ? ` · ${hot.counts.week} check-ins this week`
                : ' · under the reporting floor this week'}
            </Typography>
          ) : (
            <Typography variant="body2" color="text.secondary">
              Nothing counted yet
            </Typography>
          )}
        </Paper>
      </Box>

      <Typography variant="subtitle2" gutterBottom>
        Heat by area
      </Typography>
      <Box sx={{ mb: 2 }} data-testid="pulse-heat">
        {snapshot.heat.map(row => (
          <Box
            key={`${row.state}|${row.city}`}
            sx={{ mb: 1 }}
            data-testid={`pulse-heat-row-${row.city.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`}
          >
            <Box sx={{ display: 'flex', gap: 1, alignItems: 'baseline', flexWrap: 'wrap' }}>
              <Typography variant="body2" sx={{ fontWeight: 600 }}>
                {row.city}
              </Typography>
              {row.area ? (
                <Typography variant="body2" color="text.secondary">
                  {row.area}
                </Typography>
              ) : null}
              <Typography variant="body2" color="text.secondary">
                {row.feel} — this week: {floorText(row.counts.week)}
              </Typography>
            </Box>
            <Box sx={{ height: 8, borderRadius: 1, bgcolor: 'action.hover', overflow: 'hidden' }}>
              <Box
                sx={{
                  height: '100%',
                  width: `${row.barPct}%`,
                  bgcolor: FEEL_COLOR[row.feel] ?? '#90a4ae',
                }}
              />
            </Box>
          </Box>
        ))}
      </Box>

      <Typography variant="subtitle2" gutterBottom>
        Soft notifications
      </Typography>
      <Box data-testid="pulse-notices">
        {notices.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            Nothing to report yet — a notice lands here when a place crosses a crowd threshold.
          </Typography>
        ) : (
          notices.map(n => (
            <Typography
              key={n.id}
              variant="body2"
              color="text.secondary"
              data-testid="pulse-notice"
            >
              {new Date(`${n.day}T12:00:00`).toLocaleDateString(undefined, {
                month: 'short',
                day: 'numeric',
              })}{' '}
              — {n.text}
            </Typography>
          ))
        )}
      </Box>
    </Paper>
  );
};

// One venue's saved profile, readable in place, with the owner's
// decision buttons while it is waiting on him.
const VenueCard: React.FC<{
  row: VenueApplicationRow;
  busy: boolean;
  onAct: (row: VenueApplicationRow, status: VenueStatus) => void;
}> = ({ row, busy, onAct }) => (
  <Paper variant="outlined" sx={{ p: 2, mb: 1 }}>
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
        {row.venue_name}
      </Typography>
      <Chip
        size="small"
        color={
          row.status === 'applied'
            ? 'warning'
            : row.status === 'live'
              ? 'success'
              : row.status === 'approved'
                ? 'info'
                : 'default'
        }
        label={STATUS_LABEL[row.status]}
      />
    </Box>
    <Typography variant="body2" color="text.secondary">
      {row.venue_type} · {row.city}, {stateName(row.state)}
      {row.best_night ? ` · Best Battle Night: ${row.best_night}` : ''}
    </Typography>
    <Typography variant="body2" color="text.secondary">
      Contact: {row.contact_name} · {row.email}
      {row.phone ? ` · ${row.phone}` : ''}
      {row.social ? ` · ${row.social}` : ''}
    </Typography>
    {row.perk_idea && (
      <Typography variant="body2" color="text.secondary">
        Perk they'd offer: {row.perk_idea}
      </Typography>
    )}
    {row.notes && (
      <Typography variant="body2" color="text.secondary">
        Notes: {row.notes}
      </Typography>
    )}
    <Typography variant="caption" color="text.secondary">
      Ref {row.ref} · Applied {new Date(row.created_at).toLocaleDateString()}
    </Typography>
    <VisitsLine targetId={row.id} />
    <Box sx={{ display: 'flex', gap: 1, mt: 1, flexWrap: 'wrap' }}>
      {row.status === 'applied' && (
        <>
          <Button
            size="small"
            variant="contained"
            color="success"
            disabled={busy}
            onClick={() => onAct(row, 'approved')}
          >
            Approve
          </Button>
          <Button
            size="small"
            variant="outlined"
            color="error"
            disabled={busy}
            onClick={() => onAct(row, 'declined')}
          >
            Decline
          </Button>
        </>
      )}
      {row.status === 'approved' && (
        <Button size="small" variant="contained" disabled={busy} onClick={() => onAct(row, 'live')}>
          Mark live
        </Button>
      )}
      {row.status === 'declined' && (
        <Button
          size="small"
          variant="outlined"
          disabled={busy}
          onClick={() => onAct(row, 'applied')}
        >
          Reconsider
        </Button>
      )}
    </Box>
  </Paper>
);

const AdminVenues: React.FC = () => {
  const ownerMode = useOwnerMode();
  const portalUnlocked = usePortalUnlocked();
  const navigate = useNavigate();
  const { user } = useAuth();
  const ownerByEmail = isOwnerEmail(user?.email);

  const [backend, setBackend] = useState<'probing' | 'live' | 'missing' | 'unknown'>('probing');
  const [rows, setRows] = useState<VenueApplicationRow[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [open, setOpen] = useState<Set<string>>(new Set(['region:West', 'state:CA']));

  // Pulse's demo crowd seed lands once, and only when the window
  // actually opens (an owner or a portal unlock is looking at it).
  useMemo(() => {
    if (ownerMode || portalUnlocked) ensurePulseSeed();
  }, [ownerMode, portalUnlocked]);

  const toggle = (key: string) =>
    setOpen(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  const load = useCallback(async () => {
    const state = await probeVenueBackend();
    setBackend(state);
    if (state === 'live' && ownerByEmail) {
      const res = await fetchVenueApplications();
      if (res.missing) setBackend('missing');
      else if (res.error) setLoadError(res.error);
      else setRows(res.rows);
    }
  }, [ownerByEmail]);

  useEffect(() => {
    if (ownerMode || portalUnlocked) void load();
  }, [ownerMode, portalUnlocked, load]);

  // Lock (Round 37-V2): re-locks the portal door — clears the
  // session unlock, never the stored password hash — and steps
  // back out to the Profile page the door lives on.
  const handleLock = () => {
    lockPortal();
    navigate('/profile');
  };

  const act = async (row: VenueApplicationRow, status: VenueStatus) => {
    setBusyId(row.id);
    setActionError(null);
    const res = await setVenueStatus(row.id, status);
    setBusyId(null);
    if (res.error || !res.row) {
      setActionError(res.error ?? 'That change did not go through.');
      return;
    }
    setRows(prev => prev.map(r => (r.id === res.row!.id ? res.row! : r)));
  };

  // The demo refill stations ride the same drill-down as an
  // operation under their map home: Los Angeles, SoCal, California.
  // Labelled demo, exactly as they are on the map itself.
  const stationCity = useMemo(
    () => ({
      state: 'CA',
      area: 'SoCal' as string | null,
      city: 'Los Angeles',
      stations: REFILL_STATIONS,
    }),
    []
  );

  const tree = useMemo(() => {
    return VENUE_REGIONS.map(region => {
      const regionRows = rows.filter(r => r.region === region);
      const states = statesInRegion(region).map(st => {
        const stateRows = regionRows.filter(r => r.state === st.code);
        // Group this state's rows by area (null = no area), then city A–Z.
        const cityMap = new Map<
          string,
          { area: string | null; city: string; rows: VenueApplicationRow[] }
        >();
        for (const r of stateRows) {
          const area = r.area ?? areaForLocation(r.state, r.city);
          const key = `${area ?? ''}|${r.city.trim().toLowerCase()}`;
          const entry = cityMap.get(key) ?? { area, city: r.city.trim(), rows: [] };
          entry.rows.push(r);
          cityMap.set(key, entry);
        }
        let cities = [...cityMap.values()].sort((a, b) => a.city.localeCompare(b.city));
        let stationsHere = 0;
        if (st.code === stationCity.state) {
          stationsHere = stationCity.stations.length;
          const hasLa = cities.some(c => c.city.toLowerCase() === stationCity.city.toLowerCase());
          if (!hasLa) {
            cities = [...cities, { area: stationCity.area, city: stationCity.city, rows: [] }].sort(
              (a, b) => a.city.localeCompare(b.city)
            );
          }
        }
        return { state: st, rows: stateRows, cities, stationsHere };
      });
      return { region, rows: regionRows, states };
    });
  }, [rows, stationCity]);

  const waiting = rows.filter(r => r.status === 'applied');

  // ROUTE GUARD: a direct arrival with neither Owner Mode nor a
  // portal unlock this session sees nothing — no door, no data,
  // no hints about what lives here. A portal-unlocked arrival
  // passes to the window, where the data states below speak
  // honestly (records themselves still need an owner sign-in).
  if (!ownerMode && !portalUnlocked) {
    return (
      <Container maxWidth="sm" sx={{ py: 5 }}>
        <Typography variant="body1" color="text.secondary">
          This page isn't available.
        </Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
        <Typography variant="h4" gutterBottom sx={{ flexGrow: 1 }}>
          Administrator — Venue operations
        </Typography>
        {portalUnlocked && (
          <Button
            size="small"
            variant="outlined"
            onClick={handleLock}
            data-testid="admin-portal-lock"
          >
            🔒 Lock
          </Button>
        )}
      </Box>
      <Typography variant="body2" color="text.secondary" paragraph>
        Your window on the venue business: applications waiting on you, the venues you've approved
        and their saved profiles, and the refill stations on the map — organized region by region —
        plus Pulse, the crowd counted in aggregate. Counts only in here: no names, no player data of
        any kind, nothing that can point at a person.
      </Typography>

      <PulseSection />

      {backend === 'probing' && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="body1">Checking the venue inbox…</Typography>
        </Paper>
      )}

      {backend === 'missing' && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            The venue inbox isn't switched on yet
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            The applications table doesn't exist yet, so the For Venues form can't save anywhere —
            and it says so, plainly, instead of pretending. One step lights this whole window up:
            paste <strong>glacer-venue-backend-migration-v1.sql</strong> (in the GLACER files) into
            the Supabase SQL Editor and run it. No redeploy needed — this page checks on its own.
          </Typography>
          <Typography variant="body2" color="text.secondary">
            The drill-down below is live and honest in the meantime: it shows the operations that
            exist today (the demo refill stations) and an empty seat for every state.
          </Typography>
        </Paper>
      )}

      {backend === 'unknown' && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="body1">
            Couldn't check the venue inbox just now — reload to try again. Nothing here is guessed
            in the meantime.
          </Typography>
        </Paper>
      )}

      {backend === 'live' && !ownerByEmail && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Sign in with an owner email to open the inbox
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Owner Mode is on for this device, but application records — venue contact details
            included — open only for a signed-in owner account. That's the lock that keeps them
            private. Sign in with one of your addresses and this window loads everything.
          </Typography>
        </Paper>
      )}

      {loadError && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="body1" color="error">
            Applications didn't load: {loadError}
          </Typography>
        </Paper>
      )}
      {actionError && (
        <Paper sx={{ p: 2, mb: 3 }}>
          <Typography variant="body2" color="error">
            {actionError}
          </Typography>
        </Paper>
      )}

      {backend === 'live' && ownerByEmail && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Waiting on you ({waiting.length})
          </Typography>
          {waiting.length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              No applications waiting. New ones land here the moment a venue applies.
            </Typography>
          ) : (
            waiting.map(r => <VenueCard key={r.id} row={r} busy={busyId === r.id} onAct={act} />)
          )}
        </Paper>
      )}

      {tree.map(({ region, rows: regionRows, states }) => {
        const regionKey = `region:${region}`;
        const regionOpen = open.has(regionKey);
        const regionStations = region === 'West' ? stationCity.stations.length : 0;
        return (
          <Paper key={region} sx={{ p: 2, mb: 2 }}>
            <Box
              sx={{ display: 'flex', alignItems: 'center', gap: 1, cursor: 'pointer' }}
              onClick={() => toggle(regionKey)}
            >
              <Typography variant="h6" sx={{ flexGrow: 1 }}>
                {regionOpen ? '▾' : '▸'} {region}
              </Typography>
              <CountChips counts={countRows(regionRows)} stations={regionStations || undefined} />
            </Box>
            {regionOpen &&
              states.map(({ state, rows: stateRows, cities, stationsHere }) => {
                const stateKey = `state:${state.code}`;
                const stateOpen = open.has(stateKey);
                return (
                  <Box key={state.code} sx={{ ml: 2, mt: 1 }}>
                    <Box
                      sx={{ display: 'flex', alignItems: 'center', gap: 1, cursor: 'pointer' }}
                      onClick={() => toggle(stateKey)}
                    >
                      <Typography variant="subtitle1" sx={{ flexGrow: 1, fontWeight: 600 }}>
                        {stateOpen ? '▾' : '▸'} {state.name}
                      </Typography>
                      <CountChips
                        counts={countRows(stateRows)}
                        stations={stationsHere || undefined}
                      />
                    </Box>
                    {stateOpen && (
                      <Box sx={{ ml: 2, mt: 1 }}>
                        {cities.length === 0 && (
                          <Typography variant="body2" color="text.secondary">
                            No venues yet in {state.name} — applications will land here.
                          </Typography>
                        )}
                        {cities.map(c => {
                          const cityKey = `city:${state.code}:${c.area ?? ''}:${c.city.toLowerCase()}`;
                          const cityOpen = open.has(cityKey);
                          const isStationCity =
                            state.code === stationCity.state &&
                            c.city.toLowerCase() === stationCity.city.toLowerCase();
                          return (
                            <Box key={cityKey} sx={{ mb: 1 }}>
                              <Box
                                sx={{
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: 1,
                                  cursor: 'pointer',
                                }}
                                onClick={() => toggle(cityKey)}
                              >
                                <Typography variant="body1" sx={{ flexGrow: 1, fontWeight: 600 }}>
                                  {cityOpen ? '▾' : '▸'} {c.city}
                                  {c.area ? ` · ${c.area}` : ''}
                                </Typography>
                                <CountChips
                                  counts={countRows(c.rows)}
                                  stations={isStationCity ? stationCity.stations.length : undefined}
                                />
                              </Box>
                              {cityOpen && (
                                <Box sx={{ ml: 2, mt: 1 }}>
                                  {c.rows.map(r => (
                                    <VenueCard
                                      key={r.id}
                                      row={r}
                                      busy={busyId === r.id}
                                      onAct={act}
                                    />
                                  ))}
                                  {isStationCity &&
                                    stationCity.stations.map(s => (
                                      <Paper key={s.id} variant="outlined" sx={{ p: 2, mb: 1 }}>
                                        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                                          ⛽ {s.name}
                                        </Typography>
                                        <Typography variant="body2" color="text.secondary">
                                          Refill station on the game map (demo) — players collect
                                          potions here.
                                        </Typography>
                                        <VisitsLine targetId={s.id} />
                                      </Paper>
                                    ))}
                                  {c.rows.length === 0 && !isStationCity && (
                                    <Typography variant="body2" color="text.secondary">
                                      Nothing running in {c.city} yet.
                                    </Typography>
                                  )}
                                </Box>
                              )}
                            </Box>
                          );
                        })}
                      </Box>
                    )}
                  </Box>
                );
              })}
          </Paper>
        );
      })}
    </Container>
  );
};

export default AdminVenues;
