// PULSE — the admin window's aggregate read on GLACER activity
// (Round 37-V3, Eddie 2026-11-20 ~18:45: "I do need some of that
// data for the venues" — heat maps, new-user counts, where people
// are checking in, the hottest area, per-venue visit counts, and
// "a soft admin notification of at least something — not the exact
// people, but that there were people there").
//
// This module is THE aggregation seam: every number the Pulse
// window shows is computed here, from a named source, through one
// interface — so Phase 2 can swap the source (real backend
// check-in events) without touching the window. Only the lazy
// admin chunk imports this file.
//
// THE LAW (Eddie's, clarified 18:45 — this module lives or dies
// by it): the ban is on INDIVIDUAL data. No names, no per-person
// anything, no live map of people, no location trails — not even
// for Eddie. AGGREGATES are wanted, under these binding rules:
//   - SUPPRESSION FLOOR = 10. A count tied to a place shows a
//     numeral ONLY at 10 or more; below that it renders as words
//     ("a few so far — under the reporting floor", "none counted
//     yet"), never a small numeral that could single someone out.
//     Global totals (all check-ins, total accounts) are Eddie's
//     own business metrics and may show at any size.
//   - INVISIBLE EXCLUDED AT THE SOURCE. visibleEvents() below is
//     the only stream any count is computed from, and its first
//     act is dropping invisible-flagged events. The demo seed
//     never emits them at all (same structural exclusion as the
//     place-tag crowd: a person nobody can see is not part of the
//     signal a place gives off).
//   - CHECK-IN-VERIFIED ONLY. Tallies come solely from check-ins
//     and station collects the app already emits (see
//     utils/pulseActivity.ts). Nothing new is tracked.
//   - ROLLED-UP, NOT LIVE. Periods are today / this calendar week
//     / all time in the ledger. No event is ever rendered; no
//     timestamp finer than a day exists anywhere in Pulse.
//   - NO PUBLIC COUNTS is untouched: player-facing surfaces keep
//     qualitative feel only. This module serves the admin window
//     and nothing else.
//
// SOURCES TODAY, honestly:
//   - ACTIVITY (check-ins, heat, visits, notices): the on-device
//     demo layer — a deterministic seeded crowd derived from the
//     demo venues' visible regulars and scheduled buzz (the same
//     stand-ins placeTags.ts documents), plus this device's own
//     real check-in/collect tallies. Labelled DEMO in the window.
//   - NEW USERS: REAL FIRST — a count-only query (head count, no
//     rows ever returned) against public.profiles under the
//     signed-in session. If there is no session or the count
//     can't be read, the card falls back to a seeded demo tally,
//     labelled DEMO. A count is all that ever crosses the wire:
//     no account row, name or email is read by this module.

import { DEMO_VENUES } from '../data/venues';
import { REFILL_STATIONS } from '../data/stations';
import { buzzForVenue } from '../data/venueBuzz';
import { areaForLocation } from './venueAreas';
import { supabase } from './supabaseClient';
import { localDateString } from './presence';
import {
  PULSE_NOTICES_KEY,
  PULSE_SIGNUPS_KEY,
  isThisWeek,
  loadPulseStore,
  savePulseStore,
  type PulseEvent,
} from './pulseActivity';

export const PULSE_FLOOR = 10;

// ------------------------------------------------------------------
// Targets: the places Pulse can count. Demo venues carry the game's
// own area vocabulary (Hollywood · San Fernando Valley · Santa
// Monica); stations sit in Los Angeles. areaForLocation rolls each
// city up to its in-state area (SoCal) for the drill-down grouping.
// Application venues are NOT targets — they have no activity source
// until Phase 2, so their counts read zero (qualitative) honestly.
// ------------------------------------------------------------------

export interface PulseTarget {
  id: string;
  label: string;
  kind: 'venue' | 'station';
  state: string;
  /** In-state area from the venueAreas roll-up (e.g. SoCal). */
  area: string | null;
  /** The neighbourhood/city label the heat list ranks by. */
  city: string;
}

export const PULSE_TARGETS: PulseTarget[] = [
  ...DEMO_VENUES.map(v => ({
    id: v.id,
    label: v.name,
    kind: 'venue' as const,
    state: 'CA',
    area: areaForLocation('CA', v.area),
    city: v.area,
  })),
  ...REFILL_STATIONS.map(s => ({
    id: s.id,
    label: s.name,
    kind: 'station' as const,
    state: 'CA',
    area: areaForLocation('CA', 'Los Angeles'),
    city: 'Los Angeles',
  })),
];

const TARGET_BY_ID = new Map(PULSE_TARGETS.map(t => [t.id, t]));

export function pulseTarget(id: string): PulseTarget | undefined {
  return TARGET_BY_ID.get(id);
}

// ------------------------------------------------------------------
// The demo seed. Deterministic (seeded PRNG, stable across reloads
// — slow and sticky by construction, like the place tags): the
// trailing 28 days of crowd tallies derived from each demo venue's
// VISIBLE regulars (invisible regulars generate nothing — the
// exclusion is structural) lifted by a scheduled event, and a
// per-station draw. Also seeds the demo signup tallies used only
// when the real profiles count can't be read.
// ------------------------------------------------------------------

function hashSeed(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function mulberry32(seed: number): () => number {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const STATION_DRAW: Record<string, number> = {
  'station-echo-spring': 1.0,
  'station-neon-kiosk': 2.8,
  'station-marble-fountain': 1.9,
  'station-tidepool-kiosk': 1.2,
};

function dayKeyDaysAgo(daysAgo: number, now: Date): string {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  d.setDate(d.getDate() - daysAgo);
  return localDateString(d);
}

export function ensurePulseSeed(now: Date = new Date()): void {
  const store = loadPulseStore();
  if (!store.seeded) {
    const events: PulseEvent[] = [...store.events];
    const bases: { id: string; base: number }[] = [];
    for (const v of DEMO_VENUES) {
      const visibleRegulars = v.people.filter(p => p.visibility !== 'invisible').length;
      const eventLift = buzzForVenue(v.id)?.event ? 1.6 : 0;
      bases.push({ id: v.id, base: visibleRegulars * 1.1 + eventLift + 0.6 });
    }
    for (const s of REFILL_STATIONS) {
      bases.push({ id: s.id, base: STATION_DRAW[s.id] ?? 1.5 });
    }
    for (let ago = 27; ago >= 0; ago--) {
      const day = dayKeyDaysAgo(ago, now);
      const dow = new Date(`${day}T12:00:00`).getDay();
      const weekend = dow === 0 || dow === 5 || dow === 6 ? 1.25 : 1;
      for (const { id, base } of bases) {
        const rng = mulberry32(hashSeed(`pulse:${id}:${day}`));
        const count = Math.max(0, Math.round(base * weekend * (0.7 + rng() * 0.6)));
        for (let i = 0; i < count; i++) events.push({ t: id, d: day, src: 'demo' });
      }
    }
    savePulseStore({ v: 1, seeded: true, events });
  }
  try {
    if (localStorage.getItem(PULSE_SIGNUPS_KEY) === null) {
      const days: string[] = [];
      for (let ago = 27; ago >= 0; ago--) {
        const day = dayKeyDaysAgo(ago, now);
        const rng = mulberry32(hashSeed(`pulse-signups:${day}`));
        const n = Math.floor(rng() * 3) + (ago === 0 ? 1 : 0);
        for (let i = 0; i < n; i++) days.push(day);
      }
      localStorage.setItem(PULSE_SIGNUPS_KEY, JSON.stringify(days));
    }
  } catch {
    // Private mode: the demo signup fallback just reads as empty.
  }
}

// ------------------------------------------------------------------
// Aggregation. visibleEvents() is the ONLY stream any count below
// is computed from — its first act is the invisible exclusion.
// ------------------------------------------------------------------

export function visiblePulseEvents(): PulseEvent[] {
  return loadPulseStore().events.filter(e => !e.inv);
}

export interface PulseCounts {
  today: number;
  week: number;
  total: number;
}

function countEvents(events: PulseEvent[], now: Date): PulseCounts {
  const todayKey = localDateString(now);
  let today = 0;
  let week = 0;
  for (const e of events) {
    if (e.d === todayKey) today++;
    if (isThisWeek(e.d, now)) week++;
  }
  return { today, week, total: events.length };
}

export function pulseCountsFor(targetId: string, now: Date = new Date()): PulseCounts {
  return countEvents(
    visiblePulseEvents().filter(e => e.t === targetId),
    now
  );
}

export function totalCheckinCounts(now: Date = new Date()): PulseCounts {
  return countEvents(visiblePulseEvents(), now);
}

// ------------------------------------------------------------------
// Floor-safe display. A place-tied numeral exists only at >= the
// floor; below it, words. (Global totals never pass through here.)
// ------------------------------------------------------------------

export type FloorDisplay = { kind: 'count'; n: number } | { kind: 'words'; text: string };

export function floorDisplay(n: number): FloorDisplay {
  if (n >= PULSE_FLOOR) return { kind: 'count', n };
  if (n <= 0) return { kind: 'words', text: 'none counted yet' };
  return { kind: 'words', text: 'a few so far — under the reporting floor' };
}

export function floorText(n: number): string {
  const d = floorDisplay(n);
  return d.kind === 'count' ? String(d.n) : d.text;
}

// The admin heat scale for a week's check-ins at one place/area:
// the game's feel words, banded for weekly roll-ups. The word may
// show at any size; the numeral beside it obeys the floor.
export type PulseFeel = 'Quiet' | 'Warming up' | 'Active' | 'Buzzing';

export function pulseFeel(weekCount: number): PulseFeel {
  if (weekCount >= 50) return 'Buzzing';
  if (weekCount >= 25) return 'Active';
  if (weekCount >= 1) return 'Warming up';
  return 'Quiet';
}

// ------------------------------------------------------------------
// Heat by area: targets rolled up to their city/neighbourhood,
// ranked hottest first by this week's check-ins.
// ------------------------------------------------------------------

export interface HeatRow {
  city: string;
  area: string | null;
  state: string;
  counts: PulseCounts;
  feel: PulseFeel;
  /** Bar width 0–100, relative to the hottest row's week. */
  barPct: number;
}

export function heatByArea(now: Date = new Date()): HeatRow[] {
  const events = visiblePulseEvents();
  const groups = new Map<string, { target: PulseTarget; events: PulseEvent[] }>();
  for (const t of PULSE_TARGETS) {
    const key = `${t.state}|${t.area ?? ''}|${t.city}`;
    const entry = groups.get(key) ?? { target: t, events: [] };
    entry.events.push(...events.filter(e => e.t === t.id));
    groups.set(key, entry);
  }
  const rows: HeatRow[] = [...groups.values()].map(({ target, events: ev }) => {
    const counts = countEvents(ev, now);
    return {
      city: target.city,
      area: target.area,
      state: target.state,
      counts,
      feel: pulseFeel(counts.week),
      barPct: 0,
    };
  });
  rows.sort((a, b) => b.counts.week - a.counts.week || b.counts.total - a.counts.total);
  const max = rows.reduce((m, r) => Math.max(m, r.counts.week), 0);
  for (const r of rows)
    r.barPct = max > 0 ? Math.max(4, Math.round((r.counts.week / max) * 100)) : 0;
  return rows;
}

export function hottestArea(now: Date = new Date()): HeatRow | null {
  const rows = heatByArea(now);
  return rows.length > 0 && rows[0].counts.week > 0 ? rows[0] : (rows[0] ?? null);
}

// ------------------------------------------------------------------
// Soft notifications: threshold crossings, worded as "people were
// there" — never a name, never an exact small number, never a time
// finer than the day. A venue/station crossing 10 / 25 / 50 weekly
// check-ins, or an area crossing 25 / 50, posts ONE notice per
// threshold per calendar week (dedupe id carries the week), kept
// on-device, newest first, capped.
// ------------------------------------------------------------------

export interface PulseNotice {
  id: string;
  /** Local day the notice first fired (YYYY-MM-DD). */
  day: string;
  text: string;
}

const TARGET_THRESHOLDS = [10, 25, 50];
const AREA_THRESHOLDS = [25, 50];
const MAX_NOTICES = 20;

function loadNotices(): PulseNotice[] {
  try {
    const parsed = JSON.parse(localStorage.getItem(PULSE_NOTICES_KEY) ?? '[]');
    return Array.isArray(parsed)
      ? parsed.filter(
          (n): n is PulseNotice =>
            !!n &&
            typeof n === 'object' &&
            typeof (n as PulseNotice).id === 'string' &&
            typeof (n as PulseNotice).day === 'string' &&
            typeof (n as PulseNotice).text === 'string'
        )
      : [];
  } catch {
    return [];
  }
}

export function syncPulseNotices(now: Date = new Date()): PulseNotice[] {
  const existing = loadNotices();
  const seen = new Set(existing.map(n => n.id));
  const week = weekKeyOf(now);
  const fresh: PulseNotice[] = [];
  const add = (id: string, text: string) => {
    if (seen.has(id)) return;
    seen.add(id);
    fresh.push({ id, day: localDateString(now), text });
  };
  for (const t of PULSE_TARGETS) {
    const { week: weekCount } = pulseCountsFor(t.id, now);
    for (const th of TARGET_THRESHOLDS) {
      if (weekCount >= th) {
        add(
          `target:${t.id}:${week}:${th}`,
          `People were at ${t.label} this week — it passed ${th} check-ins.`
        );
      }
    }
  }
  for (const row of heatByArea(now)) {
    for (const th of AREA_THRESHOLDS) {
      if (row.counts.week >= th) {
        add(
          `area:${row.state}:${row.city}:${week}:${th}`,
          `${row.city} is heating up — ${th}+ check-ins this week.`
        );
      }
    }
  }
  const merged = [...fresh.reverse(), ...existing].slice(0, MAX_NOTICES);
  try {
    localStorage.setItem(PULSE_NOTICES_KEY, JSON.stringify(merged));
  } catch {
    // Private mode: the feed still renders for this session.
  }
  return merged;
}

function weekKeyOf(now: Date): string {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const dow = (d.getDay() + 6) % 7;
  d.setDate(d.getDate() - dow);
  return localDateString(d);
}

// ------------------------------------------------------------------
// New users. REAL FIRST: count-only queries against
// public.profiles under the signed-in session (head counts — no
// rows ever cross the wire). No session, or any count unreadable →
// the seeded demo tally, labelled demo by the caller via `source`.
// ------------------------------------------------------------------

export interface NewUserCounts extends PulseCounts {
  source: 'live' | 'demo';
}

async function countProfiles(sinceIso?: string): Promise<number | null> {
  let q = supabase.from('profiles').select('id', { count: 'exact', head: true });
  if (sinceIso) q = q.gte('created_at', sinceIso);
  const { count, error } = await q;
  if (error || typeof count !== 'number') return null;
  return count;
}

function localMidnightIso(daysAgo: number, now: Date): string {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  d.setDate(d.getDate() - daysAgo);
  return d.toISOString();
}

export async function fetchNewUserCounts(now: Date = new Date()): Promise<NewUserCounts> {
  try {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (session) {
      const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7));
      const [total, today, week] = await Promise.all([
        countProfiles(),
        countProfiles(localMidnightIso(0, now)),
        countProfiles(monday.toISOString()),
      ]);
      if (total !== null && today !== null && week !== null) {
        return { source: 'live', total, today, week };
      }
    }
  } catch {
    // Any failure falls through to the demo tally — never a guess
    // dressed as a live number.
  }
  ensurePulseSeed(now);
  let days: string[] = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(PULSE_SIGNUPS_KEY) ?? '[]');
    if (Array.isArray(parsed)) days = parsed.filter((d): d is string => typeof d === 'string');
  } catch {
    days = [];
  }
  const todayKey = localDateString(now);
  return {
    source: 'demo',
    today: days.filter(d => d === todayKey).length,
    week: days.filter(d => isThisWeek(d, now)).length,
    total: days.length,
  };
}
